BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_MODEL (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, MANUFACTURER_PARTNER_ID VARCHAR2(36 CHAR) NOT NULL, CODE VARCHAR2(64 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(128 CHAR) NOT NULL, FORM_FACTOR VARCHAR2(32 CHAR) NOT NULL, RACK_UNITS NUMBER(5) NOT NULL, WIDTH_MM NUMBER(10) NOT NULL, DEPTH_MM NUMBER(10) NOT NULL, WEIGHT_KG NUMBER(12,3) NOT NULL, LIFECYCLE_STATUS VARCHAR2(16 CHAR) NOT NULL, DESCRIPTION VARCHAR2(4000 CHAR), VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATED_BY VARCHAR2(36 CHAR) NOT NULL, UPDATED_BY VARCHAR2(36 CHAR) NOT NULL, LAST_REASON VARCHAR2(1024 CHAR) NOT NULL, CONSTRAINT UQ_INX_DCIM_MODEL_VENDOR UNIQUE(ORGANIZATION_ID,MANUFACTURER_PARTNER_ID,CODE), CONSTRAINT CK_INX_DCIM_MODEL_DIMS CHECK(RACK_UNITS BETWEEN 1 AND 100 AND WIDTH_MM BETWEEN 1 AND 5000 AND DEPTH_MM BETWEEN 1 AND 5000 AND WEIGHT_KG>0), CONSTRAINT CK_INX_DCIM_MODEL_STATUS CHECK(LIFECYCLE_STATUS IN (''DRAFT'',''ACTIVE'',''DECOMMISSIONED'',''ARCHIVED'')), CONSTRAINT CK_INX_DCIM_MODEL_VER CHECK(VERSION>=1), CONSTRAINT CK_INX_DCIM_MODEL_TIME CHECK(UPDATED_AT>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_MODEL_PORT (MODEL_ID VARCHAR2(36 CHAR) NOT NULL, ORDINAL NUMBER(10) NOT NULL, NAME_PREFIX VARCHAR2(24 CHAR) NOT NULL, PORT_COUNT NUMBER(10) NOT NULL, PORT_KIND VARCHAR2(16 CHAR) NOT NULL, MEDIA VARCHAR2(32 CHAR) NOT NULL, CONNECTOR VARCHAR2(32 CHAR) NOT NULL, PRIMARY KEY(MODEL_ID,ORDINAL), CONSTRAINT FK_INX_DCIM_MODEL_PORT FOREIGN KEY(MODEL_ID) REFERENCES INFRANEXUM_DCIM_MODEL(ID), CONSTRAINT CK_INX_DCIM_MODEL_PORT_COUNT CHECK(PORT_COUNT BETWEEN 1 AND 512), CONSTRAINT CK_INX_DCIM_MODEL_PORT_KIND CHECK(PORT_KIND IN (''NETWORK'',''POWER'',''CONSOLE'',''FIBER'',''OTHER'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_RACK (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR) NOT NULL, ROOM_ID VARCHAR2(36 CHAR) NOT NULL, CODE VARCHAR2(64 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(128 CHAR) NOT NULL, HEIGHT_U NUMBER(5) NOT NULL, WIDTH_MM NUMBER(10) NOT NULL, DEPTH_MM NUMBER(10) NOT NULL, LIFECYCLE_STATUS VARCHAR2(16 CHAR) NOT NULL, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATED_BY VARCHAR2(36 CHAR) NOT NULL, UPDATED_BY VARCHAR2(36 CHAR) NOT NULL, LAST_REASON VARCHAR2(1024 CHAR) NOT NULL, CONSTRAINT UQ_INX_DCIM_RACK_ROOM UNIQUE(ROOM_ID,CODE), CONSTRAINT CK_INX_DCIM_RACK_DIMS CHECK(HEIGHT_U BETWEEN 1 AND 100 AND WIDTH_MM BETWEEN 1 AND 5000 AND DEPTH_MM BETWEEN 1 AND 5000), CONSTRAINT CK_INX_DCIM_RACK_STATUS CHECK(LIFECYCLE_STATUS IN (''DRAFT'',''ACTIVE'',''MAINTENANCE'',''DECOMMISSIONED'',''ARCHIVED'')), CONSTRAINT CK_INX_DCIM_RACK_VER CHECK(VERSION>=1), CONSTRAINT CK_INX_DCIM_RACK_TIME CHECK(UPDATED_AT>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_DCIM_RACK_SCOPE ON INFRANEXUM_DCIM_RACK(ORGANIZATION_ID,SUBDIVISION_ID,ROOM_ID,LIFECYCLE_STATUS,ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_EQUIP (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR) NOT NULL, RACK_ID VARCHAR2(36 CHAR) NOT NULL, MODEL_ID VARCHAR2(36 CHAR) NOT NULL, RSOT_OBJECT_ID VARCHAR2(36 CHAR) NOT NULL, ITAM_ASSET_ID VARCHAR2(36 CHAR), SERIAL_NUMBER VARCHAR2(128 CHAR), ASSET_TAG VARCHAR2(128 CHAR), START_U NUMBER(5) NOT NULL, FACE VARCHAR2(5 CHAR) NOT NULL, LIFECYCLE_STATUS VARCHAR2(16 CHAR) NOT NULL, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATED_BY VARCHAR2(36 CHAR) NOT NULL, UPDATED_BY VARCHAR2(36 CHAR) NOT NULL, LAST_REASON VARCHAR2(1024 CHAR) NOT NULL, CONSTRAINT FK_INX_DCIM_EQUIP_RACK FOREIGN KEY(RACK_ID) REFERENCES INFRANEXUM_DCIM_RACK(ID), CONSTRAINT FK_INX_DCIM_EQUIP_MODEL FOREIGN KEY(MODEL_ID) REFERENCES INFRANEXUM_DCIM_MODEL(ID), CONSTRAINT UQ_INX_DCIM_EQUIP_RSOT UNIQUE(RSOT_OBJECT_ID), CONSTRAINT UQ_INX_DCIM_EQUIP_SERIAL UNIQUE(SERIAL_NUMBER), CONSTRAINT CK_INX_DCIM_EQUIP_U CHECK(START_U BETWEEN 1 AND 100), CONSTRAINT CK_INX_DCIM_EQUIP_FACE CHECK(FACE IN (''front'',''rear'')), CONSTRAINT CK_INX_DCIM_EQUIP_STATUS CHECK(LIFECYCLE_STATUS IN (''ACTIVE'',''MAINTENANCE'',''DECOMMISSIONED'',''ARCHIVED'')), CONSTRAINT CK_INX_DCIM_EQUIP_VER CHECK(VERSION>=1), CONSTRAINT CK_INX_DCIM_EQUIP_TIME CHECK(UPDATED_AT>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_DCIM_EQUIP_RACK ON INFRANEXUM_DCIM_EQUIP(RACK_ID,LIFECYCLE_STATUS,START_U,ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_PORT (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, EQUIPMENT_ID VARCHAR2(36 CHAR) NOT NULL, PORT_NAME VARCHAR2(64 CHAR) NOT NULL, PORT_KIND VARCHAR2(16 CHAR) NOT NULL, MEDIA VARCHAR2(32 CHAR) NOT NULL, CONNECTOR VARCHAR2(32 CHAR) NOT NULL, CONSTRAINT FK_INX_DCIM_PORT_EQUIP FOREIGN KEY(EQUIPMENT_ID) REFERENCES INFRANEXUM_DCIM_EQUIP(ID), CONSTRAINT UQ_INX_DCIM_PORT_NAME UNIQUE(EQUIPMENT_ID,PORT_NAME), CONSTRAINT CK_INX_DCIM_PORT_KIND CHECK(PORT_KIND IN (''NETWORK'',''POWER'',''CONSOLE'',''FIBER'',''OTHER'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_DCIM_PORT_EQUIP ON INFRANEXUM_DCIM_PORT(EQUIPMENT_ID,ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_CABLE (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR) NOT NULL, PORT_A_ID VARCHAR2(36 CHAR) NOT NULL, PORT_B_ID VARCHAR2(36 CHAR) NOT NULL, LABEL VARCHAR2(128 CHAR) NOT NULL, MEDIA VARCHAR2(32 CHAR) NOT NULL, CONNECTOR VARCHAR2(32 CHAR) NOT NULL, LIFECYCLE_STATUS VARCHAR2(16 CHAR) NOT NULL, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CREATED_BY VARCHAR2(36 CHAR) NOT NULL, UPDATED_BY VARCHAR2(36 CHAR) NOT NULL, LAST_REASON VARCHAR2(1024 CHAR) NOT NULL, CONSTRAINT FK_INX_DCIM_CABLE_A FOREIGN KEY(PORT_A_ID) REFERENCES INFRANEXUM_DCIM_PORT(ID), CONSTRAINT FK_INX_DCIM_CABLE_B FOREIGN KEY(PORT_B_ID) REFERENCES INFRANEXUM_DCIM_PORT(ID), CONSTRAINT CK_INX_DCIM_CABLE_ENDPOINT CHECK(PORT_A_ID<>PORT_B_ID), CONSTRAINT CK_INX_DCIM_CABLE_STATUS CHECK(LIFECYCLE_STATUS IN (''ACTIVE'',''DECOMMISSIONED'',''ARCHIVED'')), CONSTRAINT CK_INX_DCIM_CABLE_VER CHECK(VERSION>=1), CONSTRAINT CK_INX_DCIM_CABLE_TIME CHECK(UPDATED_AT>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_DCIM_CABLE_SCOPE ON INFRANEXUM_DCIM_CABLE(ORGANIZATION_ID,SUBDIVISION_ID,LIFECYCLE_STATUS,ID)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX UQ_INX_DCIM_CABLE_A ON INFRANEXUM_DCIM_CABLE(CASE WHEN LIFECYCLE_STATUS=''ACTIVE'' THEN PORT_A_ID END)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX UQ_INX_DCIM_CABLE_B ON INFRANEXUM_DCIM_CABLE(CASE WHEN LIFECYCLE_STATUS=''ACTIVE'' THEN PORT_B_ID END)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_DCIM_PHYS_DEDUP (IDEMPOTENCY_KEY VARCHAR2(200 CHAR) PRIMARY KEY, PAYLOAD_SHA256 CHAR(64 CHAR) NOT NULL, OPERATION_NAME VARCHAR2(80 CHAR) NOT NULL, RESULT_ID VARCHAR2(36 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_DCIM_PHYS_HASH CHECK(REGEXP_LIKE(PAYLOAD_SHA256,''^[0-9a-f]{64}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
